const ids = {
  "1:28":"Button","1:31":"Text Field","1:36":"Status Bar","1:46":"Home Indicator",
  "3:6":"Logo_Travelin",
  "4:13":"Photo_Aerial_Island","4:16":"Photo_Avatar_Cat","4:19":"Photo_Hot_Air_Balloons",
  "4:22":"Photo_Hotel_Room","4:25":"Photo_Mount_Bromo","4:28":"Photo_Labengki_Sombori","4:31":"Photo_Sailing_Komodo",
  "3:73":"Icon_Account","3:21":"Icon_Apple","3:64":"Icon_Bus","3:12":"Icon_Chevron_Down","3:55":"Icon_Coin",
  "3:61":"Icon_Deals","3:25":"Icon_Facebook","3:33":"Icon_Ferry","3:43":"Icon_Flight","3:18":"Icon_Google",
  "3:58":"Icon_Home","3:40":"Icon_Hotel","3:49":"Icon_Landing","3:9":"Icon_Plane","3:52":"Icon_Search",
  "3:28":"Icon_Star","3:46":"Icon_Takeoff","3:68":"Icon_Ticket","3:37":"Icon_Train"
};
// layout positions: row0 basics at y=0, icons row at y=200 (size 24), photos row at y=280 (h=200), logo
const cloned = {};
let xIcon = -10000;
const photoW = { "Photo_Aerial_Island":150, "Photo_Avatar_Cat":133, "Photo_Hot_Air_Balloons":300, "Photo_Hotel_Room":287, "Photo_Mount_Bromo":300, "Photo_Labengki_Sombori":300, "Photo_Sailing_Komodo":300 };
let xPhoto = -10000;
for (const [id, name] of Object.entries(ids)) {
  const node = await figma.getNodeByIdAsync(id);
  if (!node) return "MISSING " + id;
  const c = node.clone();
  ws.appendChild(c);
  c.name = name;
  if (name.startsWith("Icon_")) {
    c.resizeWithoutConstraints(24,24);
    c.x = xIcon; c.y = -10000 + 220;
    xIcon += 40;
  } else if (name.startsWith("Photo_")) {
    const w = photoW[name] || 200;
    c.resizeWithoutConstraints(w, Math.round(w * node.height/node.width));
    c.x = xPhoto; c.y = -10000 + 280;
    xPhoto += w + 24;
  } else if (name === "Logo_Travelin") {
    c.x = -10000; c.y = -10000 + 520;
  } else {
    // Button, Text Field, Status Bar, Home Indicator
    c.x = -10000; c.y = -10000 + (name==="Button"?0 : name==="Text Field"?70 : name==="Status Bar"?140 : 200);
  }
  cloned[name] = c.id;
}
return JSON.stringify(cloned);

async function info(id){ const n = await figma.getNodeByIdAsync(id); 
  const kids = [];
  for (const c of n.children){
    kids.push({id:c.id,name:c.name,type:c.type,w:Math.round(c.width),h:Math.round(c.height),x:Math.round(c.x),y:Math.round(c.y),
      fills:'fills' in c ? c.fills.map(f=>f.type===("SOLID")?f.type+":"+JSON.stringify(f.color):f.type).join(",") : null});
  }
  return {id:n.id,name:n.name,type:n.type,w:n.width,h:n.height,layoutMode:n.layoutMode||null,constraints:n.constraints||null,kids};
}
const a = await info("7:22"); // photo
const b = await info("7:50"); // icon flight
const c = await info("7:18"); // logo
const d = await info("7:6");  // status bar
return JSON.stringify({a,b,c,d},null,1);

const names = ["Text Field","Icon_Flight","Icon_Star","Icon_Coin","Icon_Search","Status Bar","Icon_Deals","Icon_Apple","Icon_Google"];
const out = {};
for (const n of figma.currentPage.children){
  if (names.includes(n.name) && (n.type==="COMPONENT")){
    const list = [];
    n.findAll(c=>{ 
      let f=null;
      if ('fills' in c && Array.isArray(c.fills)) f = c.fills.map(x=>x.type+"@"+(x.opacity!==undefined?x.opacity:1)+":"+(x.color?JSON.stringify(x.color):x.type)).join("|");
      list.push({id:c.id,name:c.name,type:c.type,f:f?f.slice(0,120):null, visible:c.visible});
      return false;
    });
    out[n.name] = {nId:n.id, list};
  }
}
return JSON.stringify(out,null,1);

