function iconInst(name,parent,x,y,size,color,a){
  const inst = findComp(name).createInstance();
  parent.appendChild(inst);
  const s = size/Math.max(inst.width,inst.height);
  inst.rescale(s);
  inst.x = x; inst.y = y;
  if (color){ inst.findAll(n=>{ if(n.type==="VECTOR"||n.type==="BOOLEAN_OPERATION"||n.type==="STAR"||n.type==="ELLIPSE"||n.type==="RECTANGLE"){ try{ if(n.fills&&n.fills.length||n.fills) n.fills=[solid(color,a??1)]; if(n.strokes&&n.strokes.length) n.strokes=[solid(color,a??1)]; }catch(e){} } return false; }); }
